namespace {
void need(bool value,const char*message){if(!value)throw std::runtime_error(message);}
struct Pattern:cell::ui::Editor{
 bool pointer(const cell::ui::PointerEvent&)override{return false;}
 void paint(cell::ui::Canvas&canvas,cell::ui::Rect area)override{const std::uint32_t colours[]{0xffee2222,0xff22dd44,0xff2255ee,0xffeebb22};for(int y=0;y<int(area.height);++y)canvas.fill({0,double(y),area.width,1},cell::ui::Color(colours[y%4]));}
 cell::ui::Point constrainSize(cell::ui::Point p)const noexcept override{return p;}
 bool preserveAspectRatio()const noexcept override{return false;}
};
void pump(cell::ui::Window&window,int milliseconds){const auto end=std::chrono::steady_clock::now()+std::chrono::milliseconds(milliseconds);do{window.poll();std::this_thread::sleep_for(std::chrono::milliseconds(1));}while(std::chrono::steady_clock::now()<end);}
int component(unsigned long pixel,unsigned long mask){if(!mask)return 0;const auto shift=std::countr_zero(mask);return int(((pixel&mask)>>shift)*255/(mask>>shift));}
void checkImage(Display*d,cell::ui::Window&window,int width,int height){pump(window,25);XSync(d,False);auto*image=XGetImage(d,window.nativeHandle(),0,0,unsigned(width),unsigned(height),AllPlanes,ZPixmap);need(image,"Native image readback failed");const std::uint32_t colours[]{0xffee2222,0xff22dd44,0xff2255ee,0xffeebb22};bool exact=true;for(int y=0;y<height;++y)for(int x=0;x<width;++x){const auto pixel=XGetPixel(image,x,y);const auto expected=colours[y%4];const int tolerance=image->depth<=16?8:1;exact=exact&&std::abs(component(pixel,image->red_mask)-int((expected>>16)&255))<=tolerance&&std::abs(component(pixel,image->green_mask)-int((expected>>8)&255))<=tolerance&&std::abs(component(pixel,image->blue_mask)-int(expected&255))<=tolerance;}XDestroyImage(image);need(exact,"Native window upload has a stripe, stride, pixel-order or visual mismatch");}
std::string readClipboard(Display*d,::Window requestor,cell::ui::Window&window){const auto clipboard=XInternAtom(d,"CLIPBOARD",False),utf8=XInternAtom(d,"UTF8_STRING",False),property=XInternAtom(d,"CELL_EXTERNAL_CONSUMER",False),incr=XInternAtom(d,"INCR",False);XDeleteProperty(d,requestor,property);XConvertSelection(d,clipboard,utf8,property,requestor,CurrentTime);XFlush(d);bool incremental=false;std::string result;const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(4);while(std::chrono::steady_clock::now()<deadline){window.poll();while(XPending(d)){XEvent event{};XNextEvent(d,&event);const bool notified=event.type==SelectionNotify&&event.xselection.selection==clipboard;const bool chunk=incremental&&event.type==PropertyNotify&&event.xproperty.atom==property&&event.xproperty.state==PropertyNewValue;if(!notified&&!chunk)continue;if(notified&&event.xselection.property==None)throw std::runtime_error("External clipboard request was rejected");Atom type{};int format{};unsigned long count{},remaining{};unsigned char*bytes{};need(XGetWindowProperty(d,requestor,property,0,1<<20,True,AnyPropertyType,&type,&format,&count,&remaining,&bytes)==Success,"Clipboard property read failed");if(type==incr){incremental=true;XDeleteProperty(d,requestor,property);XFlush(d);if(bytes)XFree(bytes);continue;}need(format==8&&remaining==0,"Clipboard payload was incomplete");if(count)result.append(reinterpret_cast<const char*>(bytes),count);if(bytes)XFree(bytes);XFlush(d);if(!incremental||count==0)return result;}std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("External clipboard transfer timed out");}
}
int main(){try{
 auto*d=XOpenDisplay(nullptr);need(d,"Owned X server is unavailable");const int screen=DefaultScreen(d);const auto root=RootWindow(d,screen);int tested=0;
 for(int depth:{16,24,32}){XVisualInfo query{};query.screen=screen;query.depth=depth;query.c_class=TrueColor;int count{};auto*visuals=XGetVisualInfo(d,VisualScreenMask|VisualDepthMask|VisualClassMask,&query,&count);if(!visuals||!count){if(visuals)XFree(visuals);continue;}auto visual=visuals[0];XFree(visuals);const auto colormap=XCreateColormap(d,root,visual.visual,AllocNone);XSetWindowAttributes attributes{};attributes.colormap=colormap;attributes.override_redirect=True;attributes.border_pixel=0;const auto parent=XCreateWindow(d,root,0,0,700,540,0,depth,InputOutput,visual.visual,CWColormap|CWOverrideRedirect|CWBorderPixel,&attributes);XMapWindow(d,parent);XSync(d,False);
  Pattern pattern;cell::ui::Window window(pattern);need(window.open(parent,641,483),"Cannot open inherited-visual native window");window.show(true);checkImage(d,window,641,483);need(window.resize(639,477),"Native odd-width resize failed");checkImage(d,window,639,477);
  const auto requestor=XCreateSimpleWindow(d,root,0,0,1,1,0,0,0);XSelectInput(d,requestor,PropertyChangeMask);const std::string text="Cell — 音楽 🎤 / 100%";cell::ui::widgets::Clipboard::setText(text);need(readClipboard(d,requestor,window)==text,"External UTF-8 clipboard bytes changed");std::string large;while(large.size()<180000)large+=text;cell::ui::widgets::Clipboard::setText(large);need(readClipboard(d,requestor,window)==large,"Incremental external clipboard bytes changed");XDestroyWindow(d,requestor);
  XDestroyWindow(d,parent);XSync(d,False);pump(window,20);need(!window.isOpen(),"A destroyed host parent left a live native editor handle");window.close();XFreeColormap(d,colormap);++tested;std::cout<<"PASS native X11 depth "<<depth<<": full pixel readback after odd-stride resize, UTF-8 and INCR clipboard with independent client, host-parent destruction\n";
 }
 need(tested>0,"No usable X11 visual was tested");const auto dead=cell::ui::checked::createWindow(d,root,1,1);need(dead!=None,"Checked window creation failed");need(cell::ui::checked::destroyWindow(d,dead)==Success,"Checked window teardown failed");need(cell::ui::checked::mapWindow(d,dead)==BadWindow,"Invalid host window did not produce a local checked error");::Window qr{},qp{},*children{};unsigned count{};need(!cell::ui::checked::queryTree(d,dead,&qr,&qp,&children,&count)&&!children&&!count,"Dead focus ancestor did not fail locally");XSync(d,False);XCloseDisplay(d);return 0;
}catch(const std::exception&e){std::cerr<<"FAIL native X11: "<<e.what()<<'\n';return 1;}}
